  "font-not-shapable": "draw standard 14 fonts with FontRegistry::encode, or shape with an embedded font",
  "tounicode-conflict": "mark the second occurrence with /ActualText so extraction gets its text",
  "whole-font-rebuilt": "check that the font's licence allows this, or use a static TrueType or CFF version",
  "invalid-image": "pass the complete bytes of a JPEG or PNG file to Image::jpeg or Image::png",
  "unsupported-image": "convert it to a baseline or progressive 8-bit JPEG, or to PNG",
  "image-too-large": "scale the image down before adding it",
  "image-data-length": "pass exactly 4 bytes (RGBA) per pixel, row by row",
  "invalid-icc-profile": "pass a complete ICC profile with a Gray, RGB or CMYK data colour space",
  "color-components": "give one component per channel of the colour space (/N of the ICC profile)",
  "invalid-color": "write the colour as # followed by 3 or 6 hexadecimal digits",
  "invalid-geometry": "use finite coordinates, positive page sizes and /UserUnit, non-negative line widths and dashes, a miter limit of at least 1, and images of at least one pixel",
  "text-overflow": "make the box taller or the text shorter, or use Overflow::Clip and read TextLayout::overflow",
